import os
from typing import Any, Dict, List, Optional

import requests


class TextContentSafety:
    """
    Text content safety evaluator using Perspective API.

    The allow/deny decision is based on category thresholds applied to
    Perspective scores for the text.
    """

    API_URL = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"

    def __init__(
        self,
        api_key: Optional[str] = None,
        thresholds: Optional[Dict[str, float]] = None,
        languages: Optional[List[str]] = None,
        timeout: float = 10.0,
    ) -> None:
        self.api_key = api_key or os.getenv("PERSPECTIVE_API_KEY")
        if not self.api_key:
            raise ValueError("PERSPECTIVE_API_KEY is required")

        self.thresholds = thresholds or {
            "TOXICITY": 0.70,
            "SEVERE_TOXICITY": 0.50,
            "INSULT": 0.75,
            "THREAT": 0.40,
            "PROFANITY": 0.80,
            "IDENTITY_ATTACK": 0.60,
        }
        self.languages = languages or ["en"]
        self.timeout = timeout

    def analyze(self, text: str) -> Dict[str, Any]:
        if not isinstance(text, str) or not text.strip():
            raise ValueError("text must be a non-empty string")

        payload = {
            "comment": {"text": text},
            "requestedAttributes": {category: {} for category in self.thresholds},
            "languages": self.languages,
            "doNotStore": True,
        }

        response = requests.post(
            f"{self.API_URL}?key={self.api_key}",
            json=payload,
            timeout=self.timeout,
        )
        response.raise_for_status()
        data = response.json()

        scores = {}
        attr = data.get("attributeScores", {})
        for category in self.thresholds:
            score = (
                attr.get(category, {})
                .get("summaryScore", {})
                .get("value", 0.0)
            )
            scores[category] = float(score)

        violations = {
            category: {
                "score": score,
                "threshold": self.thresholds[category],
                "allowed": score < self.thresholds[category],
            }
            for category, score in scores.items()
            if score >= self.thresholds[category]
        }

        allowed = len(violations) == 0

        return {
            "allowed": allowed,
            "scores": scores,
            "violations": violations,
            "raw": data,
        }

    def allow_text(self, text: str) -> bool:
        return bool(self.analyze(text)["allowed"])


def check_text_content_safety(
    text: str,
    thresholds: Optional[Dict[str, float]] = None,
    api_key: Optional[str] = None,
) -> bool:
    return TextContentSafety(api_key=api_key, thresholds=thresholds).allow_text(text)
